-- SafetyTraining v20.039
-- Datore di lavoro 16h: revisione didattica v2 allineata all'Accordo Stato-Regioni 17/04/2025.
-- 4 macro-blocchi interni x 240 minuti, 16 Learning Unit x 60 minuti.
-- La ripartizione interna NON rappresenta una durata normativa prescritta per singolo modulo.
-- Test Builder e banca domande finale non vengono modificati.

do $do$
declare
  r record;
  v_lu_id uuid;
  v_course_id uuid;
  v_course_version_id uuid;
  v_module_id uuid;
begin
  for r in select * from (values
    ('datore:ruolo-contesto-sistema','DL01 · Ruolo del datore di lavoro e sistema legislativo',60,'Identificare il ruolo del datore di lavoro nel contesto organizzativo e collegarlo al sistema legislativo della salute e sicurezza.',jsonb_build_object('didactic_version','datore-v2','code','DL01','minutes',60,'slide_title','Essere datore di lavoro significa governare il sistema, non solo firmare documenti','summary','Il datore di lavoro deve riconoscere il proprio ruolo prevenzionistico nel contesto reale dell’organizzazione e comprendere come le decisioni aziendali incidono sulla salute e sicurezza.','detail','Si parte dal sistema legislativo e dall’identificazione del datore di lavoro per arrivare al concetto di responsabilità organizzativa effettiva: struttura, poteri, risorse, processi e persone.','question','Quali decisioni aziendali fanno emergere concretamente il ruolo del datore di lavoro nella prevenzione?','case','L’azienda cresce, apre una nuova unità operativa e distribuisce poteri gestionali a più figure. Chi governa realmente le decisioni che incidono sulla sicurezza e come deve essere chiarito il perimetro?','common_errors',jsonb_build_array('Ridurre il ruolo alla firma dei documenti.','Confondere organigramma societario e assetto prevenzionistico.','Non aggiornare ruoli e poteri quando cambia l’organizzazione.'),'procedure',jsonb_build_array('Mappa struttura','Identifica poteri','Collega decisioni e responsabilità','Comunica il perimetro','Riesamina ai cambiamenti'))),
    ('datore:soggetti-obblighi-nondelegabili','DL02 · Soggetti della prevenzione, obblighi e presidio delle funzioni non delegabili',60,'Conoscere soggetti, compiti e obblighi del sistema di prevenzione e distinguere le funzioni che richiedono presidio diretto del datore di lavoro.',jsonb_build_object('didactic_version','datore-v2','code','DL02','minutes',60,'slide_title','Delegare attività non significa perdere il governo del sistema','summary','Il datore organizza un sistema fatto di dirigenti, preposti, RSPP, medico competente, RLS, addetti e lavoratori, mantenendo il presidio delle responsabilità proprie del ruolo.','question','Quali elementi non possono essere lasciati senza un presidio diretto e verificabile del datore di lavoro?','case','L’azienda ha nominato tutte le figure previste, ma il DVR non viene riesaminato da anni e nessuno sa chi verifica l’efficacia delle misure. Il sistema è davvero governato?','common_errors',jsonb_build_array('Pensare che le nomine sostituiscano il governo.','Non distinguere supporto tecnico e responsabilità decisionale.','Non prevedere riesame e verifica delle misure.'),'procedure',jsonb_build_array('Elenca figure','Assegna compiti','Definisci flussi','Mantieni i presidi diretti','Verifica funzionamento'))),
    ('datore:delega-responsabilita-231','DL03 · Delega di funzioni, responsabilità e D.Lgs. 231/2001',60,'Comprendere condizioni e limiti della delega, responsabilità civile e penale e logica della responsabilità amministrativa d’impresa.',jsonb_build_object('didactic_version','datore-v2','code','DL03','minutes',60,'slide_title','La delega è un assetto organizzativo, non uno scarico di responsabilità','summary','Una delega efficace richiede chiarezza di funzioni, poteri e risorse e deve inserirsi in un sistema che resta governato e verificato.','question','Come capisci se una delega è realmente operativa e non solo formale?','case','Un responsabile riceve una delega sulla manutenzione ma non dispone di budget autonomo e deve chiedere autorizzazione per ogni fermo impianto. Quale criticità organizzativa emerge?','common_errors',jsonb_build_array('Delegare senza attribuire poteri reali.','Confondere delega con mera assegnazione di compiti.','Non verificare nel tempo coerenza tra delega e organizzazione.'),'procedure',jsonb_build_array('Definisci funzione','Attribuisci poteri','Assegna risorse','Comunica','Verifica nel tempo'))),
    ('datore:istituzioni-vigilanza-inclusione','DL04 · Sistema istituzionale, vigilanza, violenza/molestie e inclusione',60,'Conoscere organi istituzionali e procedure ispettive e integrare prevenzione di violenza, molestie e inclusione nei processi aziendali.',jsonb_build_object('didactic_version','datore-v2','code','DL04','minutes',60,'slide_title','Un sistema di prevenzione deve reggere anche quando viene osservato dall’esterno','summary','ASL, INL, VVF e INAIL hanno funzioni differenti. La qualità del sistema emerge dalla coerenza tra organizzazione, documenti, prassi e capacità di gestire anche rischi organizzativi e inclusione.','question','Quali evidenze mostrano che un sistema è realmente applicato e non solo documentato?','case','Durante un controllo emergono procedure corrette ma prassi differenti tra reparti e segnalazioni sensibili senza una presa in carico definita. Da dove parte il datore?','common_errors',jsonb_build_array('Prepararsi ai controlli solo con documenti.','Trattare molestie e inclusione come temi separati dalla SSL.','Non definire canali di segnalazione e presa in carico.'),'procedure',jsonb_build_array('Mappa obblighi','Verifica prassi','Apri canali di segnalazione','Correggi scostamenti','Riesamina'))),
    ('datore:standard-tecnici-documentazione','DL05 · Standard tecnico-strutturali, conformità e documentazione',60,'Governare la conformità tecnico-strutturale di attrezzature, impianti, luoghi di lavoro e agenti di rischio attraverso responsabilità, verifiche e documentazione.',jsonb_build_object('didactic_version','datore-v2','code','DL05','minutes',60,'slide_title','La conformità deve essere mantenuta, non solo ottenuta una volta','summary','Certificazioni, verifiche, manutenzioni e documentazione devono essere inserite in un processo con owner, scadenze, controlli e gestione delle anomalie.','question','Come distingui un documento presente da un requisito realmente mantenuto nel tempo?','case','Un impianto ha certificazione iniziale ma manutenzioni arretrate e modifiche successive non tracciate. La documentazione basta a dimostrare il controllo?','common_errors',jsonb_build_array('Confondere certificato storico con stato attuale.','Non gestire scadenze e modifiche.','Non assegnare responsabilità sulle anomalie.'),'procedure',jsonb_build_array('Censisci asset','Verifica requisiti','Pianifica controlli','Gestisci modifiche','Chiudi anomalie'))),
    ('datore:valutazione-rischi-misure','DL06 · Valutazione dei rischi e programma delle misure',60,'Trasformare la valutazione dei rischi in decisioni, priorità, misure, responsabilità, risorse e riesame.',jsonb_build_object('didactic_version','datore-v2','code','DL06','minutes',60,'slide_title','Il DVR è un processo decisionale, non il punto di arrivo','summary','La valutazione dei rischi deve alimentare misure tecniche, organizzative e procedurali con priorità, risorse e controllo dell’efficacia.','question','Quando una misura prevista nel DVR può dirsi realmente implementata ed efficace?','case','Il DVR prevede una misura tecnica costosa; il budget slitta di sei mesi. Quali misure temporanee, responsabilità e criteri di riesame devi formalizzare?','common_errors',jsonb_build_array('Considerare il DVR concluso dopo la firma.','Misure senza owner o scadenza.','Temporanei che diventano permanenti senza riesame.'),'procedure',jsonb_build_array('Valuta','Prioritizza','Decidi misura','Assegna owner','Finanzia','Verifica','Riesamina'))),
    ('datore:protezione-collettiva-gruppi','DL07 · Protezione collettiva, DPI e tutela dei gruppi esposti a rischi particolari',60,'Applicare la gerarchia delle misure e considerare stress, gravidanza, genere, età e altre condizioni rilevanti nella valutazione e nelle misure.',jsonb_build_object('didactic_version','datore-v2','code','DL07','minutes',60,'slide_title','Prima si elimina o riduce il rischio alla fonte, poi si protegge la persona','summary','Le decisioni del datore devono privilegiare misure collettive e organizzative rispetto alla sola protezione individuale e considerare gruppi con esposizioni o vulnerabilità specifiche.','question','Quando il ricorso al DPI sta nascondendo una misura collettiva o organizzativa non affrontata?','case','Per un reparto rumoroso l’unica misura adottata da anni è la cuffia antirumore, nonostante esistano interventi tecnici possibili. Come riesamini la decisione?','common_errors',jsonb_build_array('Usare il DPI come prima risposta automatica.','Applicare misure identiche senza considerare differenze rilevanti.','Non riesaminare misure quando evolve la tecnica.'),'procedure',jsonb_build_array('Elimina','Riduci alla fonte','Proteggi collettivamente','Organizza','Usa DPI residui','Verifica gruppi specifici'))),
    ('datore:risorse-cambiamento-pianificazione','DL08 · Risorse, cambiamento organizzativo e pianificazione della prevenzione',60,'Integrare salute e sicurezza in budget, acquisti, manutenzione, cambiamenti organizzativi e decisioni di business.',jsonb_build_object('didactic_version','datore-v2','code','DL08','minutes',60,'slide_title','Ogni cambiamento aziendale modifica anche il profilo di rischio','summary','Nuovi impianti, turni, sedi, fornitori, tecnologie o processi devono attivare una valutazione preventiva delle ricadute sulla sicurezza.','question','Quali decisioni aziendali dovrebbero avere sempre un safety gate prima dell’approvazione?','case','Viene acquistata una nuova macchina per aumentare la produttività, ma layout, manutenzione e formazione vengono affrontati dopo la consegna. Dove è fallito il processo?','common_errors',jsonb_build_array('Coinvolgere la sicurezza a decisione già presa.','Separare budget e prevenzione.','Non valutare impatti su persone, layout e competenze.'),'procedure',jsonb_build_array('Descrivi cambiamento','Valuta impatti','Definisci requisiti','Assegna budget','Forma','Autorizza','Riesamina'))),
    ('datore:appalti-duvri-interferenze','DL09 · Appalti, interferenze e DUVRI',60,'Governare qualificazione, cooperazione, coordinamento e rischi interferenziali nei contratti e negli appalti.',jsonb_build_object('didactic_version','datore-v2','code','DL09','minutes',60,'slide_title','L’appalto crea un sistema condiviso di rischio','summary','DUVRI, informazioni e coordinamento devono restare coerenti con attività, tempi, spazi e variazioni reali.','question','Quali interferenze possono nascere senza che le lavorazioni siano tecnicamente simili?','case','Un’impresa esterna anticipa la manutenzione e occupa una zona prevista per la logistica interna. Il documento esistente non contempla la sovrapposizione. Cosa deve succedere prima di ripartire?','common_errors',jsonb_build_array('Trattare il DUVRI come documento statico.','Non aggiornare il coordinamento alle variazioni.','Non assegnare responsabilità di area.'),'procedure',jsonb_build_array('Qualifica','Informa','Mappa interferenze','Coordina','Autorizza','Verifica'))),
    ('datore:emergenze-primo-soccorso-incendio','DL10 · Organizzazione delle emergenze, primo soccorso e prevenzione incendi',60,'Assicurare una capacità di risposta alle emergenze coerente con turni, persone, luoghi, attività e cambiamenti reali.',jsonb_build_object('didactic_version','datore-v2','code','DL10','minutes',60,'slide_title','L’emergenza si governa prima che inizi','summary','Nomine, piani e dotazioni devono tradursi in una capacità reale di risposta in ogni configurazione significativa dell’organizzazione.','question','Come dimostri che il sistema di emergenza funziona anche nei turni meno presidiati?','case','Nel turno serale mancano alcuni addetti, una via è temporaneamente modificata e sono presenti tecnici esterni. Il piano generale è invariato. È sufficiente?','common_errors',jsonb_build_array('Contare solo gli addetti nominati.','Non riesaminare il piano dopo modifiche temporanee.','Non integrare appalti e emergenza.'),'procedure',jsonb_build_array('Mappa scenari','Verifica coperture','Controlla dotazioni e vie','Comunica','Esercita','Correggi'))),
    ('datore:sorveglianza-sanitaria-flussi','DL11 · Sorveglianza sanitaria e flussi organizzativi',60,'Integrare la sorveglianza sanitaria nei processi aziendali rispettando le competenze del medico competente e gestendo correttamente i flussi organizzativi.',jsonb_build_object('didactic_version','datore-v2','code','DL11','minutes',60,'slide_title','La sorveglianza sanitaria è un processo aziendale, non una scadenza isolata','summary','Il datore deve assicurare che mansioni, rischi, idoneità, prescrizioni e cambiamenti organizzativi entrino nei flussi corretti senza invadere l’autonomia sanitaria del medico competente.','question','Che cosa deve cambiare nell’organizzazione quando emergono prescrizioni o segnali sanitari rilevanti per il lavoro?','case','Una prescrizione limita una specifica esposizione, ma il reparto continua ad assegnare turni come prima per mancanza di comunicazione organizzativa. Dove si è spezzato il processo?','common_errors',jsonb_build_array('Trattare le visite come adempimento separato.','Non tradurre le prescrizioni in organizzazione.','Chiedere o diffondere informazioni sanitarie non pertinenti.'),'procedure',jsonb_build_array('Pianifica','Informa il medico sui rischi','Ricevi esiti organizzativamente rilevanti','Adatta il lavoro','Aggiorna misure','Riesamina'))),
    ('datore:informazione-formazione-consultazione','DL12 · Informazione, formazione, partecipazione e consultazione',60,'Governare competenze, comunicazioni obbligatorie e partecipazione dei soggetti della prevenzione, inclusa la consultazione dell’RLS.',jsonb_build_object('didactic_version','datore-v2','code','DL12','minutes',60,'slide_title','La formazione è un processo: bisogno, erogazione, apprendimento, efficacia','summary','Il datore deve assicurare che informazione, formazione e addestramento siano coerenti con rischi e mansioni e che partecipazione e consultazione siano integrate nelle decisioni.','question','Quando un attestato non è sufficiente a dimostrare che la formazione ha prodotto il risultato atteso?','case','Un lavoratore ha attestato aggiornato ma durante l’attività applica una procedura superata. Come deve reagire il sistema oltre al semplice richiamo?','common_errors',jsonb_build_array('Equivalere attestato a competenza.','Formare senza osservare il trasferimento sul lavoro.','Consultare solo a decisione conclusa quando è prevista partecipazione.'),'procedure',jsonb_build_array('Analizza bisogno','Forma','Verifica apprendimento','Osserva applicazione','Consulta','Correggi'))),
    ('datore:vigilanza-procedure-efficacia','DL13 · Vigilanza sulle procedure e verifica dell’efficacia',60,'Impostare controlli periodici sull’applicazione e sull’efficacia delle procedure e delle istruzioni di lavoro in sicurezza.',jsonb_build_object('didactic_version','datore-v2','code','DL13','minutes',60,'slide_title','Una procedura esiste davvero solo se viene applicata e funziona','summary','Il datore deve creare un sistema di vigilanza organizzativa che non dipenda da controlli occasionali ma produca informazioni, correzioni e riesame.','question','Quale differenza c’è tra verificare che una procedura sia seguita e verificare che sia efficace?','case','La procedura viene rispettata formalmente ma continuano near miss analoghi. Il sistema è conforme ma efficace? Quale decisione serve?','common_errors',jsonb_build_array('Misurare solo il rispetto formale.','Chiudere azioni senza verifica di efficacia.','Ignorare pattern di near miss ripetuti.'),'procedure',jsonb_build_array('Osserva','Misura','Analizza cause','Correggi','Verifica efficacia','Riesamina'))),
    ('datore:mog-sistemi-gestione','DL14 · Modelli organizzativi e sistemi di gestione',60,'Comprendere il valore organizzativo di MOG e sistemi di gestione volontari come strumenti di presidio, tracciabilità e miglioramento.',jsonb_build_object('didactic_version','datore-v2','code','DL14','minutes',60,'slide_title','Un modello organizzativo deve rendere il sistema più governabile','summary','MOG e sistemi di gestione hanno valore quando chiariscono responsabilità, processi, controlli, flussi e riesame, non quando aggiungono carta.','question','Quale problema deve risolvere un sistema di gestione per essere utile e non burocratico?','case','L’azienda introduce nuove procedure e moduli, ma i tempi di chiusura delle anomalie peggiorano. Il sistema sta migliorando o complicando il processo?','common_errors',jsonb_build_array('Equivalere sistema di gestione a manuale.','Aggiungere moduli senza semplificare processi.','Non misurare tempi e risultati.'),'procedure',jsonb_build_array('Definisci processi','Assegna owner','Stabilisci controlli','Misura','Correggi','Riesamina'))),
    ('datore:costi-benefici-indicatori','DL15 · Costi della mancata sicurezza, benefici e indicatori di governo',60,'Leggere costi diretti e indiretti della mancata sicurezza e usare indicatori per orientare priorità e investimenti.',jsonb_build_object('didactic_version','datore-v2','code','DL15','minutes',60,'slide_title','La sicurezza è anche una decisione economica: misurare ciò che costa non prevenire','summary','Infortuni, fermate, assenze, turnover, danni, inefficienze e reputazione hanno costi spesso superiori all’investimento preventivo.','question','Quali costi non compaiono subito in bilancio ma segnalano un sistema di prevenzione fragile?','case','Un intervento tecnico viene rinviato perché costoso, mentre crescono microfermate, near miss e manutenzioni correttive. Come confronti le alternative?','common_errors',jsonb_build_array('Valutare solo il costo iniziale della misura.','Usare solo infortuni come indicatore.','Premiare la riduzione delle segnalazioni invece del miglioramento reale.'),'procedure',jsonb_build_array('Raccogli dati','Stima impatti','Confronta alternative','Definisci indicatori','Decidi','Verifica ritorno'))),
    ('datore:comunicazione-scenario-governance','DL16 · Comunicazione e scenario integrato di governance',60,'Integrare responsabilità, rischi, risorse, appalti, formazione, emergenze e indicatori in una decisione di governance tracciabile.',jsonb_build_object('didactic_version','datore-v2','code','DL16','minutes',60,'slide_title','Governare significa scegliere priorità e assicurarsi che la decisione arrivi fino al lavoro reale','summary','L’ultima unità mette il datore davanti a segnali contemporanei e richiede una decisione completa: fatti, rischio, priorità, misura immediata, risorsa, owner, scadenza, comunicazione e verifica.','question','Quale decisione cambia davvero il sistema invece di risolvere solo l’episodio?','case','Nello stesso mese aumentano near miss, un appaltatore segnala interferenze, una formazione viene rinviata per carenza di personale, alcune manutenzioni sono scadute e il budget è sotto pressione. Quali sono le prime cinque decisioni del datore di lavoro?','common_errors',jsonb_build_array('Risolvere singoli episodi senza correggere cause di sistema.','Decidere senza assegnare risorse e owner.','Comunicare la decisione senza verificare applicazione.'),'procedure',jsonb_build_array('Raccogli fatti','Prioritizza','Proteggi subito','Decidi modifica','Assegna risorsa','Nomina owner','Fissa scadenza','Comunica','Verifica','Riesamina')))
  ) x(stable_key,title,minutes,summary,content)
  loop
    insert into public.learning_units(stable_key,title,summary,default_minutes,source_group,tags,active,metadata)
    values(r.stable_key,r.title,r.summary,r.minutes,'datore_lavoro',array['datore-lavoro','asr-2025','governance','role-specific'],true,jsonb_build_object('didactic_version','datore-v2','competency_level','datore_lavoro','regulatory_basis','Accordo Stato-Regioni 17/04/2025 Rep. 59/CSR'))
    on conflict (stable_key) do update set title=excluded.title,summary=excluded.summary,default_minutes=excluded.default_minutes,source_group=excluded.source_group,tags=excluded.tags,active=true,metadata=public.learning_units.metadata||excluded.metadata,updated_at=now()
    returning id into v_lu_id;
    insert into public.learning_unit_versions(learning_unit_id,version_number,status,content,published_at)
    values(v_lu_id,1,'published',r.content,now())
    on conflict (learning_unit_id,version_number) do update set status='published',content=excluded.content,published_at=coalesce(public.learning_unit_versions.published_at,now());
  end loop;

  select id into v_course_id from public.courses where stable_key='dl_base';
  if v_course_id is not null then
    update public.courses set metadata=metadata||jsonb_build_object('didactic_preview_version','datore-v2','didactic_macro_blocks',4,'didactic_atomic_units',16,'didactic_focus','employer_governance_prevention_system','final_test_builder_paused',true,'delivery_constraint','classroom_vcs_or_elearning','classroom_allowed',true,'vcs_allowed',true,'elearning_asynchronous_allowed',true,'attendance_min_pct',90,'final_verification','test_or_interview','test_min_questions',30,'test_min_options',3,'test_passing_score_pct',70,'renewal_interval_months',60,'refresher_min_minutes',360,'construction_addon_min_minutes',360),updated_at=now() where id=v_course_id;
    insert into public.course_versions(course_id,version_number,status,syllabus_snapshot,normative_snapshot)
    values(v_course_id,2,'draft',jsonb_build_object('didactic_version','datore-v2','macro_blocks',jsonb_build_array(jsonb_build_object('key','dl-a','title','Ruolo, obblighi, responsabilità e sistema istituzionale','minutes',240),jsonb_build_object('key','dl-b','title','Valutazione dei rischi, misure, risorse e cambiamento','minutes',240),jsonb_build_object('key','dl-c','title','Appalti, emergenze, sorveglianza sanitaria e formazione','minutes',240),jsonb_build_object('key','dl-d','title','Vigilanza, MOG, indicatori, comunicazione e governance','minutes',240)),'official_module_mapping',jsonb_build_object('giuridico_normativo',jsonb_build_array('dl-a'),'organizzazione_gestione_ssl',jsonb_build_array('dl-b','dl-c','dl-d')),'atomic_learning_units',16,'total_minutes',960,'internal_didactic_allocation',true,'statutory_per_module_duration',false,'purpose','employer_governance_and_prevention_system','final_assessment_in_scope',false),jsonb_build_object('basis','Accordo Stato-Regioni 17/04/2025 Rep. 59/CSR; artt. 15, 17, 18, 30 e 37 d.lgs. 81/2008','minimum_minutes',960,'attendance_min_pct',90,'delivery',jsonb_build_object('classroom',true,'vcs',true,'elearning_asynchronous',true),'verification',jsonb_build_object('mode','test_or_interview','test_min_questions',30,'test_min_options',3,'passing_score_pct',70),'refresher',jsonb_build_object('interval_months',60,'minimum_minutes',360),'construction_addon',jsonb_build_object('required_when','datore_impresa_affidataria_art_97','minimum_minutes',360)))
    on conflict (course_id,version_number) do update set status='draft',syllabus_snapshot=excluded.syllabus_snapshot,normative_snapshot=excluded.normative_snapshot returning id into v_course_version_id;

    delete from public.course_module_units where module_id in (select id from public.course_modules where course_version_id=v_course_version_id);
    delete from public.course_modules where course_version_id=v_course_version_id;

    insert into public.course_modules(course_version_id,module_key,title,position,nominal_minutes) values(v_course_version_id,'dl-a','DL-A · Ruolo, obblighi, responsabilità e sistema istituzionale',0,240) returning id into v_module_id;
    insert into public.course_module_units(module_id,unit_version_id,position,required,min_active_seconds,requires_comprehension,completion_rules)
    select v_module_id,luv.id,x.pos,true,0,true,jsonb_build_object('didactic_version','datore-v2','delivery','classroom_vcs_or_elearning') from (values ('datore:ruolo-contesto-sistema',1),('datore:soggetti-obblighi-nondelegabili',2),('datore:delega-responsabilita-231',3),('datore:istituzioni-vigilanza-inclusione',4)) x(key,pos) join public.learning_units lu on lu.stable_key=x.key join public.learning_unit_versions luv on luv.learning_unit_id=lu.id and luv.version_number=1;

    insert into public.course_modules(course_version_id,module_key,title,position,nominal_minutes) values(v_course_version_id,'dl-b','DL-B · Valutazione dei rischi, misure, risorse e cambiamento',240,240) returning id into v_module_id;
    insert into public.course_module_units(module_id,unit_version_id,position,required,min_active_seconds,requires_comprehension,completion_rules)
    select v_module_id,luv.id,x.pos,true,0,true,jsonb_build_object('didactic_version','datore-v2','delivery','classroom_vcs_or_elearning') from (values ('datore:standard-tecnici-documentazione',1),('datore:valutazione-rischi-misure',2),('datore:protezione-collettiva-gruppi',3),('datore:risorse-cambiamento-pianificazione',4)) x(key,pos) join public.learning_units lu on lu.stable_key=x.key join public.learning_unit_versions luv on luv.learning_unit_id=lu.id and luv.version_number=1;

    insert into public.course_modules(course_version_id,module_key,title,position,nominal_minutes) values(v_course_version_id,'dl-c','DL-C · Appalti, emergenze, sorveglianza sanitaria e formazione',480,240) returning id into v_module_id;
    insert into public.course_module_units(module_id,unit_version_id,position,required,min_active_seconds,requires_comprehension,completion_rules)
